/// <summary>
/// PricingAttribute of table <c>CustDirectDebitMandate</c> field PrenotificationDaysRecurring.
/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustDirectDebitMandatePrenotificationDaysRecurring extends UPSPricingAttributeCustDirectDebitMandate implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustDirectDebitMandate, PrenotificationDaysRecurring);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::Integer);
    CustDirectDebitMandate custDirectDebitMandate;

    while select custDirectDebitMandate
        group by PrenotificationDaysRecurring
    {
        if (! ret.in(custDirectDebitMandate.PrenotificationDaysRecurring))
        {
            ret.add(custDirectDebitMandate.PrenotificationDaysRecurring);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustDirectDebitMandate, PrenotificationDaysRecurring));
    qbr.value(queryValue(_value));
}
